const IMGS = ["data:image/png;base64,", "data:image/png;base64,"];
const DAYS = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo"];
const KEY = "weekend-week-v2";
function iso(d) { return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); }
function monday(d) { const x = new Date(d.getFullYear(), d.getMonth(), d.getDate()); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; }
function shift(k, n) { const [y, m, d] = k.split("-").map(Number); return iso(new Date(y, m - 1, d + 7 * n)); }
const realWeek = iso(monday(new Date()));
let wk = realWeek, data = { weeks: {} };
function W() { return data.weeks[wk] || (data.weeks[wk] = { cells: {}, notes: "" }); }
try {
  const s = JSON.parse(localStorage.getItem(KEY));
  if (s && s.weeks) data = s;
  else { const old = JSON.parse(localStorage.getItem("weekend-week-v1")); if (old) W().cells = old; }
} catch (e) {}
let cells = W().cells;
let warned = false;
function save() { try { localStorage.setItem(KEY, JSON.stringify(data)); } catch (e) { if (!warned) { warned = true; alert("Não coube no armazenamento do navegador. Tente figurinhas menores ou apague algumas."); } } }
function mk(tag, cls, text) { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
function clean(k) { const c = cells[k]; if (c && !c.t && c.s == null && c.c == null) delete cells[k]; }

document.getElementById("img0").src = IMGS[0];
document.getElementById("img1").src = IMGS[1];

const now = new Date(), realH = now.getHours(), dow = now.getDay();
const todayRaw = (dow + 6) % 7;
let nowH = realH, todayIdx = todayRaw;

function render() {
  const grid = document.getElementById("grid");
  grid.replaceChildren(mk("div", "hd"));
  DAYS.forEach((n, i) => {
    const hd = mk("div", "hd" + (i === todayIdx ? " today" : ""), n);
    const x = mk("button", "x", "×"); x.type = "button"; x.title = "Limpar " + n; x.setAttribute("aria-label", "Limpar " + n);
    x.onclick = () => {
      if (confirm("Limpar " + n + "?")) { Object.keys(cells).forEach(k => { if (k.startsWith(i + "-")) delete cells[k]; }); save(); render(); }
    };
    hd.append(x); grid.append(hd);
  });
  for (let h = 6; h < 23; h++) {
    grid.append(mk("div", "hour" + (h === nowH ? " now" : ""), h + "h"));
    DAYS.forEach((n, i) => {
      const k = i + "-" + h, d = cells[k] || {};
      const cell = mk("div", "cell" + (i === todayIdx && h === nowH ? " now" : ""));
      if (d.s != null) cell.dataset.s = d.s;
      if (d.c != null) cell.dataset.c = d.c;
      const ta = mk("textarea"); ta.rows = 2; ta.value = d.t || "";
      ta.setAttribute("aria-label", n + ", " + h + " horas");
      ta.addEventListener("input", () => { (cells[k] || (cells[k] = {})).t = ta.value; clean(k); save(); });
      const dot = mk("button", "dot"); dot.type = "button"; dot.title = "Cor do bloco"; dot.setAttribute("aria-label", "Trocar cor do bloco");
      dot.onclick = () => {
        const cur = cells[k] || (cells[k] = {}), nx = cur.c == null ? 0 : cur.c + 1;
        if (nx > 7) { delete cur.c; delete cell.dataset.c; } else { cur.c = nx; cell.dataset.c = nx; }
        clean(k); save();
      };
      cell.append(ta, dot);
      if (d.s != null) {
        const b = mk("button", "stk"); b.type = "button"; b.title = "Trocar figurinha"; b.setAttribute("aria-label", "Trocar figurinha");
        b.append(stk(d.s));
        b.onclick = () => openPop(k, b);
        cell.append(b);
      } else {
        const p = mk("button", "pick"); p.type = "button"; p.title = "Colocar figurinha"; p.setAttribute("aria-label", "Colocar figurinha");
        p.innerHTML = '<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>';
        p.onclick = () => openPop(k, p);
        cell.append(p);
      }
      grid.append(cell);
    });
  }
}

document.getElementById("clear").onclick = () => {
  if ((Object.keys(cells).length || Object.keys(W().marks || {}).length) && confirm("Apagar tudo desta semana?")) { W().cells = {}; W().marks = {}; cells = W().cells; save(); render(); renderHabits(); }
};
document.getElementById("theme").onclick = () => {
  const r = document.documentElement;
  const dark = r.dataset.theme === "dark" || (!r.dataset.theme && matchMedia("(prefers-color-scheme: dark)").matches);
  r.dataset.theme = dark ? "light" : "dark";
};
const EMO = ["⭐", "💙", "☁️", "📚", "🎧", "🐾", "☕", "🌙"];
function stk(i) {
  if (typeof i === "string") {
    const c = (data.custom || []).find(x => x.id === i);
    if (!c) return mk("span", "emo", "");
    if (c.type === "img") { const im = mk("img"); im.src = c.v; im.alt = ""; return im; }
    const s = mk("span", "emo", c.v); if ([...c.v].length > 2) s.style.fontSize = ".8rem"; return s;
  }
  if (i < IMGS.length) { const im = mk("img"); im.src = IMGS[i]; im.alt = ""; return im; }
  return mk("span", "emo", EMO[i - IMGS.length]);
}
function stickerIds() {
  const a = [];
  for (let i = 0; i < IMGS.length + EMO.length; i++) a.push(i);
  (data.custom || []).forEach(c => a.push(c.id));
  return a;
}
const pop = mk("div", "pop"); pop.hidden = true; document.body.append(pop);
function closePop() { pop.hidden = true; }
function popFor(anchor, hasCur, onPick, onRemove) {
  pop.replaceChildren();
  for (const i of stickerIds()) {
    const b = mk("button", "po"); b.type = "button"; b.setAttribute("aria-label", "Figurinha"); b.append(stk(i));
    b.onclick = () => { closePop(); onPick(i); };
    pop.append(b);
  }
  if (hasCur) {
    const r = mk("button", "po", "×"); r.type = "button"; r.title = "Remover figurinha"; r.setAttribute("aria-label", "Remover figurinha");
    r.onclick = () => { closePop(); onRemove(); };
    pop.append(r);
  }
  const nw = mk("button", "po", "＋"); nw.type = "button"; nw.title = "Criar minha figurinha"; nw.setAttribute("aria-label", "Criar minha figurinha");
  nw.onclick = () => { closePop(); openStickers(); };
  pop.append(nw);
  pop.hidden = false;
  const a = anchor.getBoundingClientRect();
  pop.style.top = (window.scrollY + a.bottom + 6) + "px";
  pop.style.left = Math.max(8, Math.min(window.scrollX + a.right - pop.offsetWidth, document.documentElement.clientWidth - pop.offsetWidth - 8)) + "px";
}
function openPop(k, anchor) {
  popFor(anchor, !!(cells[k] && cells[k].s != null),
    i => { (cells[k] || (cells[k] = {})).s = i; save(); render(); },
    () => { delete cells[k].s; clean(k); save(); render(); });
}
document.addEventListener("click", e => { if (!pop.hidden && !pop.contains(e.target) && !e.target.closest(".pick, .stk")) closePop(); });

function label(k) {
  const [y, m, d] = k.split("-").map(Number), a = new Date(y, m - 1, d), b = new Date(y, m - 1, d + 6);
  const f = x => x.toLocaleDateString("pt-BR", { day: "numeric", month: "short" }).replace(".", "");
  return f(a) + " – " + f(b);
}
function setWeek(k) {
  wk = k; cells = W().cells;
  const live = wk === realWeek;
  todayIdx = live ? todayRaw : -1; nowH = live ? realH : -1;
  document.getElementById("wlabel").textContent = label(wk);
  document.getElementById("today").hidden = live;
  closePop(); render(); renderHabits();
}
document.getElementById("prev").onclick = () => setWeek(shift(wk, -1));
document.getElementById("next").onclick = () => setWeek(shift(wk, 1));
document.getElementById("today").onclick = () => setWeek(realWeek);
document.getElementById("copy").onclick = () => {
  const nk = shift(wk, 1), dst = data.weeks[nk];
  if (dst && (Object.keys(dst.cells).length || Object.keys(dst.marks || {}).length) && !confirm("A próxima semana já tem conteúdo. Substituir?")) return;
  data.weeks[nk] = { cells: JSON.parse(JSON.stringify(W().cells)), marks: {} }; save(); setWeek(nk);
};
const $ = id => document.getElementById(id);
function fit(file, max) {
  return new Promise((res, rej) => {
    const url = URL.createObjectURL(file), im = new Image();
    im.onload = () => {
      const r = Math.min(1, max / Math.max(im.width, im.height)), c = document.createElement("canvas");
      c.width = Math.round(im.width * r); c.height = Math.round(im.height * r);
      c.getContext("2d").drawImage(im, 0, 0, c.width, c.height);
      URL.revokeObjectURL(url); res(c.toDataURL("image/png"));
    };
    im.onerror = rej; im.src = url;
  });
}
function renderMlist() {
  const l = $("mlist"); l.replaceChildren();
  const arr = data.custom || [];
  if (!arr.length) { l.append(mk("p", "mp", "Você ainda não criou nenhuma.")); return; }
  arr.forEach(c => {
    const d = mk("div", "mi"); d.append(stk(c.id));
    const x = mk("button", "del", "×"); x.type = "button"; x.setAttribute("aria-label", "Apagar figurinha");
    x.onclick = () => {
      if (!confirm("Apagar esta figurinha? Ela some dos horários onde foi usada.")) return;
      data.custom = data.custom.filter(z => z.id !== c.id);
      Object.values(data.weeks).forEach(w => Object.keys(w.cells).forEach(k => { if (w.cells[k].s === c.id) { delete w.cells[k].s; const cc = w.cells[k]; if (!cc.t && cc.c == null) delete w.cells[k]; } }));
      save(); renderMlist(); render();
    };
    d.append(x); l.append(d);
  });
}
function addCustom(type, v) {
  (data.custom || (data.custom = [])).push({ id: "c" + Date.now() + Math.random().toString(36).slice(2, 5), type, v });
  save(); renderMlist();
}
function openStickers() { renderMlist(); $("modal").hidden = false; }
$("upimg").onclick = () => $("fileStk").click();
$("fileStk").onchange = async e => {
  const f = e.target.files[0]; e.target.value = ""; if (!f) return;
  try { addCustom("img", await fit(f, 160)); } catch (x) { alert("Não consegui abrir essa imagem."); }
};
$("addtxt").onclick = () => {
  const v = [...$("txtstk").value.trim()].slice(0, 4).join("");
  if (!v) return; addCustom("txt", v); $("txtstk").value = "";
};
$("txtstk").addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); $("addtxt").click(); } });
$("mclose").onclick = () => { $("modal").hidden = true; };
$("modal").addEventListener("click", e => { if (e.target === $("modal")) $("modal").hidden = true; });
document.addEventListener("keydown", e => { if (e.key === "Escape") { $("modal").hidden = true; $("menu").hidden = true; closePop(); } });

$("more").onclick = e => { e.stopPropagation(); $("menu").hidden = !$("menu").hidden; };
$("menu").addEventListener("click", () => { $("menu").hidden = true; });
document.addEventListener("click", e => { if (!$("menu").hidden && !$("menu").contains(e.target) && !$("more").contains(e.target)) $("menu").hidden = true; });
$("mystk").onclick = openStickers;
if (!data.habits) data.habits = [{ id: "h1", name: "Beber água" }, { id: "h2", name: "Exercício" }, { id: "h3", name: "Ler um pouco" }];
const INI = ["S", "T", "Q", "Q", "S", "S", "D"];
function marks() { return W().marks || (W().marks = {}); }
function renderHabits() {
  const g = $("hgrid"); g.replaceChildren(mk("div"));
  INI.forEach((l, i) => g.append(mk("div", "hd2" + (i === todayIdx ? " today" : ""), l)));
  g.append(mk("div"));
  if (!data.habits.length) { const p = mk("p", "mp", "Nenhum hábito ainda."); p.style.gridColumn = "1 / -1"; g.append(p); }
  data.habits.forEach(h => {
    const m = (W().marks || {})[h.id] || [];
    const nm = mk("div", "hname");
    const sb = mk("button", "hs"); sb.type = "button"; sb.title = "Figurinha do hábito"; sb.setAttribute("aria-label", "Figurinha do hábito");
    if (h.s != null) sb.append(stk(h.s)); else sb.textContent = "✦";
    sb.onclick = () => popFor(sb, h.s != null, i => { h.s = i; save(); renderHabits(); }, () => { delete h.s; save(); renderHabits(); });
    const inp = mk("input"); inp.value = h.name; inp.maxLength = 40; inp.placeholder = "Nome do hábito"; inp.setAttribute("aria-label", "Nome do hábito");
    inp.addEventListener("input", () => { h.name = inp.value; save(); });
    const del = mk("button", "hdel", "×"); del.type = "button"; del.title = "Apagar hábito"; del.setAttribute("aria-label", "Apagar hábito");
    del.onclick = () => {
      if (!confirm("Apagar o hábito “" + (h.name || "sem nome") + "”?")) return;
      data.habits = data.habits.filter(x => x.id !== h.id);
      Object.values(data.weeks).forEach(w => { if (w.marks) delete w.marks[h.id]; });
      save(); renderHabits();
    };
    nm.append(sb, inp, del); g.append(nm);
    for (let d = 0; d < 7; d++) {
      const b = mk("button", "hb" + (m[d] ? " on" : ""), "★"); b.type = "button";
      b.setAttribute("aria-pressed", String(!!m[d])); b.setAttribute("aria-label", (h.name || "Hábito") + ", " + DAYS[d]);
      b.onclick = () => { const mm = marks(), arr = mm[h.id] || (mm[h.id] = [0, 0, 0, 0, 0, 0, 0]); arr[d] = arr[d] ? 0 : 1; save(); renderHabits(); };
      g.append(b);
    }
    const n = m.reduce((a, b) => a + b, 0);
    g.append(mk("div", "hcount" + (n === 7 ? " full" : ""), n + "/7"));
  });
}
$("hadd").onclick = () => {
  data.habits.push({ id: "h" + Date.now() + Math.random().toString(36).slice(2, 5), name: "" });
  save(); renderHabits();
  const ins = $("hgrid").querySelectorAll(".hname input"); ins[ins.length - 1].focus();
};
setWeek(realWeek);